/**
 * @fileoverview Report Document Text — τα κείμενα ΓΥΡΩ από τον πίνακα μιας εξαγωγής (CSV / Excel / PDF)
 * @description Γραμμή περιόδου και υποσέλιδο σελίδας — ΜΙΑ φορά για τους τρεις exporters. Ως 2026-10-30 ήταν
 *   σκληρογραμμένα αγγλικά (`Period: 2026-01-01 to …`, `Generated by … — Page 1/2`) με ωμές ημερομηνίες ISO.
 *
 * @see report-table-adapter.ts · ADR-ACC-010 §2.1.1 changelog 2026-10-30
 */

import { PRODUCT_NAME } from '@/constants/product-identity';
import { formatCalendarDate } from '@/lib/intl-utils';

import type { ResolvedPeriods } from '../../types/reports';
import type { ReportTranslate } from './report-table-adapter';

/** «Περίοδος: 1 Ιανουαρίου 2026 – 31 Δεκεμβρίου 2026» — ημέρες ημερολογίου, χωρίς ολίσθηση ζώνης ώρας. */
export function reportPeriodLine(period: ResolvedPeriods, t: ReportTranslate): string {
  return t('reports.exportDocument.period', {
    from: formatCalendarDate(period.current.from),
    to: formatCalendarDate(period.current.to),
  });
}

/** «Δημιουργήθηκε από … — Σελίδα 1/3». */
export function reportPageFooter(page: number, pages: number, t: ReportTranslate): string {
  return t('reports.exportDocument.footer', { product: PRODUCT_NAME, page, pages });
}
